import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.util.*;
public class DrawingPadForensics{
static class Broken extends JFrame{Broken(){super("Broken pad");JPanel p=new JPanel();p.setBackground(Color.WHITE);p.addMouseListener(new MouseAdapter(){public void mouseClick(MouseEvent e){Graphics g=p.getGraphics();g.setColor(Color.BLUE);g.fillOval(e.getX()-4,e.getY()-4,8,8);}});add(p);setSize(460,300);setDefaultCloseOperation(EXIT_ON_CLOSE);}}
static class HalfFixed extends JFrame{int clicks;JLabel label=new JLabel("Clicks: 0");HalfFixed(){super("Half fixed");JPanel p=new JPanel();p.setBackground(Color.WHITE);p.addMouseListener(new MouseAdapter(){@Override public void mouseClicked(MouseEvent e){clicks++;label.setText("Clicks: "+clicks);Graphics g=p.getGraphics();g.setColor(Color.BLUE);g.fillOval(e.getX()-4,e.getY()-4,8,8);}});add(p);add(label,BorderLayout.SOUTH);setSize(460,300);setDefaultCloseOperation(EXIT_ON_CLOSE);}}
static class Fixed extends JFrame{java.util.List<Point>points=new ArrayList<>();JLabel label=new JLabel("Clicks: 0");Fixed(){super("Fixed pad");JPanel p=new JPanel(){protected void paintComponent(Graphics g){super.paintComponent(g);g.setColor(Color.BLUE);for(Point q:points)g.fillOval(q.x-4,q.y-4,8,8);}};p.setBackground(Color.WHITE);p.addMouseListener(new MouseAdapter(){@Override public void mouseClicked(MouseEvent e){points.add(e.getPoint());label.setText("Clicks: "+points.size());p.repaint();}});add(p);add(label,BorderLayout.SOUTH);setSize(460,300);setDefaultCloseOperation(EXIT_ON_CLOSE);}}
public static void main(String[]a){SwingUtilities.invokeLater(()->{String[]v={"Broken","HalfFixed","Fixed"};String s=(String)JOptionPane.showInputDialog(null,"Choose version","Drawing pad",0,null,v,v[2]);JFrame f=s==null||s.equals("Fixed")?new Fixed():s.equals("Broken")?new Broken():new HalfFixed();f.setLocationRelativeTo(null);f.setVisible(true);});}}
 // mouseClick is not the MouseAdapter method; correct name is mouseClicked. @Override exposes the typo at compile time.
